'use strict';
function catalogCollections(){const p=state.searchScope==='all'||state.project==='all'?state.projects:[currentProject()].filter(Boolean);return [...new Map(p.flatMap(p=>p.collections).map(c=>[c.id,c])).values()];}
function syncSearchControls(){const active=!!state.q&&state.mode!=='records'&&state.searchScope!=='collection';$('search-kind').hidden=!active;$('work-controls').hidden=active;const select=$('search-kind');select.replaceChildren(new Option('All item types',''));catalogCollections().forEach(c=>select.append(new Option(c.label,c.id)));select.value=state.searchKind||'';}
async function searchCatalog(more=false){const gen=++state.generation;notice('');syncSearchControls();if(!more){state.rows=[];state.offset=0;$('assets').replaceChildren(node('div','empty','Searching registered catalog items…'));}
 try{const project=state.searchScope==='all'||state.project==='all'?'all':state.project;const d=await api('/api/search',{project,kind:state.searchKind||'',q:state.q,offset:state.offset});if(gen!==state.generation)return;if(Object.entries(d.snapshots).some(([id,c])=>state.projects.find(p=>p.id===id)?.commit!==c))throw Error('Snapshot changed; refresh the view.');state.rows.push(...d.items);state.offset=state.rows.length;$('assets').replaceChildren(...state.rows.map(workCard));if(!state.rows.length)$('assets').append(node('div','empty','No indexed catalog items match.'));$('category-heading').textContent='Search results';$('result-count').textContent=d.total+' catalog matches';$('more').hidden=state.offset>=d.total;document.querySelector('main footer').textContent=d.coverage;}catch(e){notice(e.message);}}
function drawAncestry(d){const nav=$('ancestry');nav.replaceChildren();[...(d.parents||[])].reverse().forEach(p=>{const b=node('button','button secondary',p.title);b.onclick=()=>inspectWork(p);nav.append(b,node('span','muted',' › '));});nav.append(node('span','',d.work.title));if(d.parents?.length){$('back-work').hidden=false;$('back-work').onclick=()=>inspectWork(d.parents[0]);}}
async function browseChildren(kind='',offset=0){const selected=state.selected,d=selected?.workDetails;if(!d)return;const w=d.work;const area=$('detail');if(!offset)area.replaceChildren(node('p','muted','Loading indexed child items…'));
 try{const page=await api('/api/children',{project:w.project,collection:w.collection,id:w.id,snapshot:d.commit,kind,offset});if(state.selected!==selected||state.tab!=='Browse')return;selected.childKind=kind;selected.childRows=offset?[...(selected.childRows||[]),...page.items]:page.items;area.replaceChildren();const filters=node('div','facet-buttons');const all=node('button','button secondary'+(!kind?' chosen':''),'All');all.onclick=()=>browseChildren();filters.append(all);Object.entries(page.kinds).forEach(([id,v])=>{const b=node('button','button secondary'+(kind===id?' chosen':''),v.label+' ('+v.count+')');b.onclick=()=>browseChildren(id);filters.append(b);});area.append(filters);selected.childRows.forEach(child=>{const b=node('button','member-button');b.append(node('strong','',child.title),node('small','',child.category+' · '+child.id));b.onclick=()=>inspectWork(child);area.append(b);});if(!page.total)area.append(node('p','callout','No child items are individually indexed for this selection. Retained packages may contain additional inputs; this does not mean none exist.'));if(selected.childRows.length<page.total){const b=node('button','button secondary','Show more items');b.onclick=()=>browseChildren(kind,selected.childRows.length);area.append(b);}}catch(e){area.replaceChildren(node('p','callout',e.message));}}
